export const LEVELS={
 easy:{id:'easy',cash:7000,reserve:3000,salary:1800,living:1400,expenseScale:1,volatility:1,incomeCut:0,cutMonths:[],bond:0,target:60,rewardBase:12,rewardStep:2,pressure:{},milestones:[[45,10],[60,15],[75,20],[90,30]],vi:['Dễ','Xây nền tảng','Dòng tiền dư $400/tháng, dự phòng $3.000. Tập quản lý vốn trước khi tăng độ khó.'],en:['Easy','Build your foundation','$400 monthly surplus and $3,000 reserve. Learn the basics before raising the difficulty.']},
 medium:{id:'medium',cash:6500,reserve:2000,salary:1700,living:1550,expenseScale:1.2,volatility:1.25,incomeCut:350,cutMonths:[4,8],bond:40,target:70,rewardBase:28,rewardStep:3,pressure:{1:450,4:250,7:250,10:250},milestones:[[50,20],[65,30],[80,40],[90,60]],vi:['Trung bình','Áp lực dòng tiền','Dư $150/tháng trước trả góp. Tháng 4 và 8 giảm $350 thu nhập. Tháng 1 có thêm $450 bắt buộc, tháng 4/7/10 thêm $250. Chi phí ×1,2; biến động ×1,25.'],en:['Medium','Cash-flow pressure','$150 surplus before installments. Income drops $350 in months 4 and 8. Extra mandatory $450 in month 1, $250 in months 4/7/10. Costs ×1.2; swings ×1.25.']},
 hard:{id:'hard',cash:5500,reserve:1500,salary:1600,living:1650,expenseScale:1.5,volatility:1.5,incomeCut:300,cutMonths:[3,6,9,12],bond:80,target:75,rewardBase:60,rewardStep:4,pressure:{1:500,3:250,5:250,7:250,9:250,11:250},milestones:[[55,35],[70,50],[85,70],[95,100]],vi:['Khó','Bảo vệ khả năng tồn tại','Thiếu $50/tháng trước trả góp. Tháng 3, 6, 9, 12 giảm $300 thu nhập. Dự phòng $1.500, tháng 1 thêm $500 bắt buộc, tháng 3/5/7/9/11 thêm $250. Chi phí ×1,5; biến động ×1,5.'],en:['Hard','Protect your ability to survive','$50 monthly deficit before installments. Income drops $300 in months 3, 6, 9 and 12. $1,500 reserve; extra $500 in month 1, $250 in months 3/5/7/9/11. Costs ×1.5; swings ×1.5.']}
};
// Retain the exact pressure of already-started pre-v22 Hard saves.
const LEGACY_HARD={...LEVELS.hard,incomeCut:500,pressure:{1:900,3:450,5:450,7:450,9:450,11:450},vi:['Khó','Luật chặng cũ','Chặng đã lưu trước bản 22: giảm $500 thu nhập ở tháng 3/6/9/12; áp lực $900 tháng 1, $450 tháng 3/5/7/9/11.'],en:['Hard','Legacy stage rules','Pre-v22 saved stage: $500 income cuts in months 3/6/9/12; $900 pressure in month 1 and $450 in months 3/5/7/9/11.']};
export const levelOf=s=>s?.difficulty==='hard'&&s.balanceVersion!==22?LEGACY_HARD:LEVELS[s?.difficulty]||LEVELS.easy;
export const essentialCost=(s,cost)=>Math.round(cost*levelOf(s).expenseScale);
export const marketRate=(s,base)=>Math.round(base*levelOf(s).volatility*10000)/10000;
export const incomeAt=(s,month=s.month)=>{const l=levelOf(s);return l.salary-(l.cutMonths.includes(month)?l.incomeCut:0);};
export const wealthBenchmark=s=>{const l=levelOf(s),initial=l.cash+l.reserve;return Math.max(initial,initial+12*(l.salary-l.living)-l.cutMonths.length*l.incomeCut);};
